// Work item WI-10000456. Disposable copy-only execution, not a new product surface.
import { readFileSync, writeFileSync, mkdirSync, mkdtempSync, rmSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { createHash } from 'node:crypto';
import { spawnSync, execFileSync } from 'node:child_process';

const root = process.cwd();
const pkg = join(root, 'packages/operator-core');
const sourceDir = join(pkg, 'lib');
const scratchRoot = join(sourceDir, '.papercusp/scratch');
mkdirSync(scratchRoot, { recursive: true });
const dir = mkdtempSync(join(scratchRoot, 'p012-replay-18327-'));
const hash = (value) => createHash('sha256').update(value).digest('hex');
const subjects = [
  { name: 'agent-obligation-providers', before: 'a0631e37ec^', absent: 'const goalStatus = portfolio.goal.status;', control: 'export function planPlacementObligation', originalTestRunId: 17999352 },
  { name: 'agent-obligation-reader', before: '1d46df0059^', absent: 'const lifecycleUnknown =', control: 'export async function readAgentObligationAgenda', originalTestRunId: 17999375 },
];
const startedAt = new Date().toISOString();
const result = { schemaVersion: 1, workItemId: 'WI-10000456', startedAt, copyOnly: true, subjects: [], verdict: 'incomplete' };
// Current tests are relocated without changing assertions. Source imports
// resolve to canonical dependencies, except the explicit adjacent subject copy.
function relocate(text, subject) {
  return text.replace(/(['"])(\.{1,2}\/[^'"]+)\1/g, (_whole, quote, spec) => {
    const mapped = spec === `./${subject}` ? `./${subject}.ts` : resolve(sourceDir, spec);
    return `${quote}${mapped}${quote}`;
  });
}
const snapshots = new Map();
try {
  for (const subject of subjects) {
    const file = join(sourceDir, `${subject.name}.ts`);
    const testFile = join(sourceDir, `${subject.name}.test.ts`);
    const current = readFileSync(file, 'utf8');
    const test = readFileSync(testFile, 'utf8');
    snapshots.set(file, hash(current));
    snapshots.set(testFile, hash(test));
    const commit = execFileSync('git', ['rev-parse', subject.before], { cwd: root, encoding: 'utf8' }).trim();
    const historical = execFileSync('git', ['show', `${commit}:packages/operator-core/lib/${subject.name}.ts`], { cwd: root, encoding: 'utf8' });
    if (!current.includes(subject.absent) || historical.includes(subject.absent)
      || !current.includes(subject.control) || !historical.includes(subject.control)) throw new Error(`Invalid historical selection for ${subject.name}`);
    const row = { name: subject.name, originalTestRunId: subject.originalTestRunId, historicalCommit: commit,
      currentSourceSha256: hash(current), historicalSourceSha256: hash(historical), currentTestSha256: hash(test), phases: [] };
    result.subjects.push(row);
    for (const [phase, source] of [['current', current], ['historical', historical]]) {
      const phaseDir = join(dir, `${subject.name}-${phase}`);
      mkdirSync(phaseDir);
      writeFileSync(join(phaseDir, `${subject.name}.ts`), relocate(source, ''));
      writeFileSync(join(phaseDir, `${subject.name}.test.ts`), relocate(test, subject.name));
      const config = join(phaseDir, 'vitest.config.ts');
      // Reuse the actual project framework, setup and reporter; remove only its
      // default scratch-directory exclusion for these exact copied test paths.
      writeFileSync(config, `import base from ${JSON.stringify(join(pkg, 'vitest.config.ts'))};\nexport default {...base, test:{...base.test, include:[${JSON.stringify(join(phaseDir, `${subject.name}.test.ts`))}], exclude:['**/node_modules/**']}};\n`);
      const report = join(phaseDir, 'result.json');
      const args = [join(root, 'node_modules/vitest/vitest.mjs'), 'run', '--config', config, '--reporter=json', `--outputFile=${report}`];
      const phaseStart = new Date().toISOString();
      const execution = spawnSync(process.execPath, args, { cwd: pkg, encoding: 'utf8',
        env: { ...process.env, PAPERCUSP_MUTATION_PROBE: '1', PAPERCUSP_MUTATION_PHASE: phase, PAPERCUSP_WORKSPACE_ID: 'papercusp-workspace', PAPERCUSP_TEST_RUN_HARNESS: 'papercusp' },
        timeout: 180000, maxBuffer: 4 * 1024 * 1024 });
      const details = JSON.parse(readFileSync(report, 'utf8'));
      const assertions = details.testResults.flatMap((file) => file.assertionResults);
      const record = { phase, command: [process.execPath, ...args], startedAt: phaseStart, finishedAt: new Date().toISOString(),
        exitCode: execution.status, signal: execution.signal, passed: assertions.filter((test) => test.status === 'passed').length,
        failed: assertions.filter((test) => test.status === 'failed').length,
        other: assertions.filter((test) => !['passed', 'failed'].includes(test.status)).length,
        failures: assertions.filter((test) => test.status === 'failed').map((test) => ({ name: test.fullName, messages: test.failureMessages })) };
      row.phases.push(record);
      console.log(JSON.stringify({ name: subject.name, phase, passed: record.passed, failed: record.failed, other: record.other, exitCode: record.exitCode }));
      if (phase === 'current' && (execution.status !== 0 || record.failed !== 0 || record.other !== 0)) throw new Error(`Current calibration failed: ${subject.name}`);
      if (phase === 'historical' && (execution.status !== 1 || record.failed === 0 || record.other !== 0)) throw new Error(`Historical comparison is not an assertion failure: ${subject.name}`);
    }
  }
  result.verdict = 'historical-failures-caught';
} catch (error) {
  result.error = String(error);
  process.exitCode = 1;
} finally {
  result.sourceUnchanged = [...snapshots].every(([file, sha]) => hash(readFileSync(file)) === sha);
  if (!result.sourceUnchanged) { result.verdict = 'source-changed-during-probe'; process.exitCode = 1; }
  result.finishedAt = new Date().toISOString();
  writeFileSync('/tmp/goal-feedback-p012-historical-recurrence-18327.json', JSON.stringify(result, null, 2));
  rmSync(dir, { recursive: true, force: true });
  console.log(JSON.stringify({ verdict: result.verdict, error: result.error, sourceUnchanged: result.sourceUnchanged }));
}
